INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q5723209', 'Battle of Vega Real', 'The Battle of Vega Real, also called the Battle of the Holy Hill or the Battle of Jáquimo, took place on 24 March 1495 on the island of Hayti between an indigenous alliance and Spanish forces, commanded by Christopher Columbus, Bartholomew Columbus and Alonso de Ojeda, with the help of indigenous people led by Guacanagaríx. The battle resulted in the defeat and capture of the Taíno leader Caonabo, ending indigenous resistance on Hayti.', 1495, 3, 27, NULL, NULL, NULL, 'day', '27 March 1495', 34, 'https://en.wikipedia.org/wiki/Battle_of_Vega_Real'),
  ('Q15145340', 'Battle of Santo Domingo', 'The Battle of Santo Domingo (1586) or the Capture of Santo Domingo was a military and naval action fought on 1 January 1586, of the recently declared Anglo-Spanish War that resulted in the assault and capture by English soldiers and sailors of the Spanish city of Santo Domingo governed by Cristóbal de Ovalle on the Spanish island of Hispaniola. The English were led by Francis Drake and was part of his Great Expedition to raid the Spanish New World in a kind of preemptive strike.', 1586, 1, 1, NULL, NULL, NULL, 'day', '1 January 1586', 34, 'https://en.wikipedia.org/wiki/Battle_of_Santo_Domingo_(1586)'),
  ('Q5502314', 'French occupation of Santo Domingo', 'In the history of the Dominican Republic, the period of Era de Francia (''Era of France'', ''French Era'', ''Age of France'' or ''French Period'') occurred in 1795 when France acquired the Captaincy General of Santo Domingo, annexed it into Saint-Domingue and briefly came to acquire the whole island of Hispaniola by the way of the Treaty of Basel, allowing Spain to cede the eastern province as a consequence of the French Revolutionary Wars. Despite its brevity, it produced important changes in society, especially in the demographic aspect, as there was a massive emigration of settlers (especially…', 1795, 7, 22, 1809, 7, 9, 'day', '22 July 1795 – 9 July 1809', 39, 'https://en.wikipedia.org/wiki/Era_de_Francia'),
  ('Q3439047', 'War of Dominican Independence', 'The Dominican War of Independence (Spanish: Guerra de Independencia Dominicana) was a war of independence that began when the Dominican Republic declared independence from the Republic of Haiti on February 27, 1844 and ended on January 24, 1856. Before the war, the island of Hispaniola had been united for 22 years when the newly independent nation, previously known as the Captaincy General of Santo Domingo, was unified with the Republic of Haiti in 1822.', 1844, NULL, NULL, 1856, NULL, NULL, 'year', '1844–1856', 57, 'https://en.wikipedia.org/wiki/Dominican_War_of_Independence'),
  ('Q4872308', 'Battle of Santiago (1844)', 'The Battle of Santiago (Spanish: Batalla de Santiago de 1844) was the second major battle of the Dominican War of Independence and was fought on the 30 March 1844, at Santiago de los Caballeros, Santiago Province. Although outnumbered, Dominican troops, part of the Army of The North and led by General José María Imbert, defeated Haitian Army troops led by General Jean-Louis Pierrot.', 1844, 3, 30, NULL, NULL, NULL, 'day', '30 March 1844', 37, 'https://en.wikipedia.org/wiki/Battle_of_Santiago_(1844)'),
  ('Q16933273', 'Spanish Province of Santo Domingo', 'The Annexation of the Dominican Republic to Spain (Spanish: Anexión de la República Dominicana a España) or Reintegration of Santo Domingo (Reintegración de Santo Domingo) was a four-year period between 1861 and 1865 during which the former Spanish possession of Santo Domingo in the eastern part of the island of Hispaniola, then the independent Dominican Republic, was occupied and annexed by the Spanish Empire, following the request of Dominican dictator Pedro Santana. The period coincided with the American Civil War, during which the United States was unable to enforce the Monroe Doctrine.', 1861, 3, 18, 1865, 7, 15, 'day', '18 March 1861 – 15 July 1865', 41, 'https://en.wikipedia.org/wiki/Spanish_annexation_of_the_Dominican_Republic'),
  ('Q16573193', 'Dominican Civil War of 1911–12', 'The Dominican Civil War that lasted from 5 December 1911 until 30 November 1912 was the bloodiest in the history of the Dominican Republic. It began as an uprising in the northwest of the country.', 1911, 12, NULL, 1912, 11, NULL, 'month', 'December 1911 – November 1912', 34, 'https://en.wikipedia.org/wiki/Dominican_Civil_War_(1911%E2%80%931912)'),
  ('Q1756207', 'United States occupation of the Dominican Republic', 'The Military Government of Santo Domingo (Spanish: Gobierno Militar de Santo Domingo) was a provisional military government established during the American occupation of the Dominican Republic that lasted from May 15, 1916 to September 18, 1924. The United States aimed to force the Dominicans to repay their large debts to European creditors, whose governments threatened military intervention.', 1924, 12, 27, NULL, NULL, NULL, 'day', '27 December 1924', 55, 'https://en.wikipedia.org/wiki/Military_Government_of_Santo_Domingo'),
  ('Q1348841', '1946 Dominican Republic earthquake', 'The 1946 Dominican Republic earthquake occurred on August 4 at 13:51 AST near Samaná, Dominican Republic. It was the largest earthquake to occur in the instrumental era in the Caribbean.', 1946, 8, 4, NULL, NULL, NULL, 'day', '4 August 1946', 39, 'https://en.wikipedia.org/wiki/1946_Dominican_Republic_earthquake'),
  ('Q28502993', 'Rebellion of the Pilots', 'The Rebellion of the Pilots was a military uprising carried out by six members of the Dominican Military Aviation (today the Dominican Air Force) on November 19, 1961, that put a definitive end to the rule of 31 years of the Trujillo dictatorship by forcing the exile of the Trujillo family from the country. It prevented Ramfis Trujillo, José Arismendy Trujillo and Héctor Bienvenido Trujillo Molina from returning to power and restoring the regime led by their brother Rafael Trujillo.', 1961, 11, 19, NULL, NULL, NULL, 'day', '19 November 1961', 26, 'https://en.wikipedia.org/wiki/Rebellion_of_the_Pilots'),
  ('Q110970039', '1963 Dominican coup d''état', 'The 1963 Dominican coup d''état was a coup d''état that took place on 25 September 1963 against President Juan Bosch in the Dominican Republic. Juan Bosch had been the first democratically elected president after the assassination of the former dictator Rafael Trujillo, but he faced criticism due to his policies, which were seen as leftist.', 1963, 9, 25, NULL, NULL, NULL, 'day', '25 September 1963', 26, 'https://en.wikipedia.org/wiki/1963_Dominican_coup_d''%C3%A9tat'),
  ('Q955457', 'Dominican Civil War', 'The Dominican Civil War (Spanish: Guerra Civil Dominicana), also known as the April Revolution (Spanish: Revolución de Abril), took place between April 24 and September 3, 1965, in Santo Domingo, Dominican Republic. It started when civilian and military supporters of the overthrown democratically elected president Juan Bosch ousted the militarily-installed dictator Donald Reid from office.', 1965, 4, 24, 1965, 9, 3, 'day', '24 April 1965 – 3 September 1965', 48, 'https://en.wikipedia.org/wiki/Dominican_Civil_War'),
  ('Q1808713', 'United States occupation of the Dominican Republic', 'The Dominican Civil War (Spanish: Guerra Civil Dominicana), also known as the April Revolution (Spanish: Revolución de Abril), took place between April 24 and September 3, 1965, in Santo Domingo, Dominican Republic. It started when civilian and military supporters of the overthrown democratically elected president Juan Bosch ousted the militarily-installed dictator Donald Reid from office.', 1965, 4, 28, 1966, 9, NULL, 'day', '28 April 1965 – September 1966', 55, 'https://en.wikipedia.org/wiki/United_States_occupation_of_the_Dominican_Republic_(1965%E2%80%9366)'),
  ('Q5290887', 'Dominicana DC-9 air disaster', 'On February 15, 1970, Dominicana de Aviación Flight 603, en route from Santo Domingo, Dominican Republic to San Juan, Puerto Rico crashed into the Caribbean Sea shortly after takeoff. The crash killed all 97 passengers and 5 crew on board, making it the deadliest aviation disaster to occur within the Dominican Republic until the crash of Birgenair Flight 301 in 1996, in the Caribbean Sea, leaving 189 dead.', 1970, 2, 15, NULL, NULL, NULL, 'day', '15 February 1970', 45, 'https://en.wikipedia.org/wiki/Dominicana_de_Aviaci%C3%B3n_Flight_603'),
  ('Q435223', 'Birgenair Flight 301', 'Birgenair Flight 301 was a chartered flight by Turkish-managed Birgenair partner Alas Nacionales from Puerto Plata in the Dominican Republic to Frankfurt, Germany, via Gander, Canada, and Berlin, Germany. On 6 February 1996, the Boeing 757 operating the route crashed shortly after take-off from Puerto Plata''s Gregorio Luperón International Airport, killing all 189 people on board.', 1996, 2, 6, NULL, NULL, NULL, 'day', '6 February 1996', 61, 'https://en.wikipedia.org/wiki/Birgenair_Flight_301'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic');
